package org.json;
import java.util.*;import com.google.gson.*;
/** Host test adapter backed by cached Gson. Not Android's JSON parser, never packaged in APK. */
public class JSONObject {
 public static final Object NULL=new Object();final JsonObject value;
 public JSONObject(){value=new JsonObject();}public JSONObject(String s){value=JsonParser.parseString(s).getAsJsonObject();}JSONObject(JsonObject v){value=v;}
 static JsonElement tree(Object v){if(v==null||v==NULL)return JsonNull.INSTANCE;if(v instanceof JSONObject)return((JSONObject)v).value;if(v instanceof JSONArray)return((JSONArray)v).value;return new Gson().toJsonTree(v);}
 static Object object(JsonElement e){if(e==null)return null;if(e.isJsonNull())return NULL;if(e.isJsonObject())return new JSONObject(e.getAsJsonObject());if(e.isJsonArray())return new JSONArray(e.getAsJsonArray());JsonPrimitive p=e.getAsJsonPrimitive();if(p.isBoolean())return p.getAsBoolean();if(p.isString())return p.getAsString();String n=p.getAsString();try{if(n.contains(".")||n.contains("e")||n.contains("E"))return Double.valueOf(n);long l=Long.parseLong(n);return l>=Integer.MIN_VALUE&&l<=Integer.MAX_VALUE?(Object)Integer.valueOf((int)l):Long.valueOf(l);}catch(Exception x){return Double.valueOf(n);}}
 public JSONObject put(String k,Object v){if(v==null)value.remove(k);else value.add(k,tree(v));return this;}public Object get(String k){if(!value.has(k))throw new IllegalArgumentException("MISSING:"+k);return object(value.get(k));}public Object opt(String k){return object(value.get(k));}public boolean has(String k){return value.has(k);}public boolean isNull(String k){return !value.has(k)||value.get(k).isJsonNull();}public Object remove(String k){return object(value.remove(k));}public int length(){return value.size();}public Iterator<String>keys(){return value.keySet().iterator();}
 public String getString(String k){Object v=get(k);if(v==NULL)throw new IllegalArgumentException("NULL:"+k);return String.valueOf(v);}public long getLong(String k){Object v=get(k);return v instanceof Number?((Number)v).longValue():Long.parseLong(String.valueOf(v));}public int getInt(String k){Object v=get(k);return v instanceof Number?((Number)v).intValue():Integer.parseInt(String.valueOf(v));}public double getDouble(String k){Object v=get(k);return v instanceof Number?((Number)v).doubleValue():Double.parseDouble(String.valueOf(v));}public boolean getBoolean(String k){Object v=get(k);if(v instanceof Boolean)return(Boolean)v;if("true".equalsIgnoreCase(String.valueOf(v)))return true;if("false".equalsIgnoreCase(String.valueOf(v)))return false;throw new IllegalArgumentException("BOOLEAN:"+k);}
 public JSONObject getJSONObject(String k){return(JSONObject)get(k);}public JSONArray getJSONArray(String k){return(JSONArray)get(k);}public JSONObject optJSONObject(String k){Object v=opt(k);return v instanceof JSONObject?(JSONObject)v:null;}public JSONArray optJSONArray(String k){Object v=opt(k);return v instanceof JSONArray?(JSONArray)v:null;}public String optString(String k,String d){return isNull(k)?d:String.valueOf(opt(k));}public String optString(String k){return optString(k,"");}public boolean optBoolean(String k){return optBoolean(k,false);}public boolean optBoolean(String k,boolean d){try{return getBoolean(k);}catch(Exception e){return d;}}public long optLong(String k,long d){try{return getLong(k);}catch(Exception e){return d;}}public long optLong(String k){return optLong(k,0);}public int optInt(String k,int d){try{return getInt(k);}catch(Exception e){return d;}}public int optInt(String k){return optInt(k,0);}public double optDouble(String k,double d){try{return getDouble(k);}catch(Exception e){return d;}}public double optDouble(String k){return optDouble(k,Double.NaN);}public static String quote(String s){return new Gson().toJson(s);}@Override public String toString(){return value.toString();}
}
